func bibtex(p post.Post) string {
	return fmt.Sprintf(`@article{daemontalk_%s,
  title = "{%s}",
  author = {Daemontalk Team},
  year = "%s",
  url = "https://daemontalk.com/blog/%s"
}`, strings.ReplaceAll(p.Slug, "-", "_"), p.Title, p.Date.Format("2006"), p.Slug)
}

